#!/usr/bin/env python3
"""Self-test of aapt2_platforms.py and verification_additions.py on scratch copies of this repository's
files, run by dependabot-gradle.yml before it trusts them with a branch. No Gradle, no network.

Usage: test_scripts.py REPO WORKDIR
"""
import re
import shutil
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
FILES = ["build.gradle.kts", "gradle/verification-metadata.xml"]


def run(script, *args):
    p = subprocess.run([sys.executable, "-I", str(HERE / script), *map(str, args)], capture_output=True, text=True)
    return p.returncode, (p.stdout + p.stderr).strip()


def copy(repo, dest):
    shutil.rmtree(dest, ignore_errors=True)
    for f in FILES:
        (dest / f).parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(repo / f, dest / f)
    return dest


def platforms(root, agp):
    """DependencyVerificationTest.aapt2IsThereForEveryPlatformTheAppIsBuiltOn, in Python."""
    meta = (root / "gradle/verification-metadata.xml").read_text()
    return {m.group(1) for m in re.finditer(r'<artifact name="aapt2-' + re.escape(agp) + r'-\d+-(\w+)\.jar">', meta)}


def main(argv):
    repo, work = Path(argv[0]), Path(argv[1])
    failed = []

    def check(name, cond, detail=""):
        print(("PASS " if cond else "FAIL ") + name + (f"  [{detail}]" if detail and not cond else ""))
        if not cond:
            failed.append(name)

    base = copy(repo, work / "base")
    old = base / "gradle/verification-metadata.xml"

    # An AGP bump as Gradle on Linux writes it: one aapt2 component, holding the Linux jar only.
    bumped = copy(repo, work / "bumped")
    script = bumped / "build.gradle.kts"
    agp = re.search(r'id\("com\.android\.application"\) version "([^"]+)"', script.read_text()).group(1)
    script.write_text(script.read_text().replace(f'application") version "{agp}"', 'application") version "99.0.0"'))
    meta = bumped / "gradle/verification-metadata.xml"
    text = meta.read_text()
    anchor = text.index('      <component group="com.android.tools.build" name="aapt2"')
    meta.write_text(text[:anchor] +
                    '      <component group="com.android.tools.build" name="aapt2" version="99.0.0-1">\n'
                    '         <artifact name="aapt2-99.0.0-1-linux.jar">\n'
                    f'            <sha256 value="{"1" * 64}" origin="Generated by Gradle"/>\n'
                    '         </artifact>\n'
                    '      </component>\n' + text[anchor:])
    check("aapt2: the bump has the Linux jar only", platforms(bumped, "99.0.0") == {"linux"})
    sums = work / "sums.txt"
    sums.write_text(f"aapt2-99.0.0-1-osx.jar {'2' * 64}\naapt2-99.0.0-1-windows.jar {'3' * 64}\n")
    code, out = run("aapt2_platforms.py", bumped, "--offline-sums", sums)
    check("aapt2: the three platforms are there", code == 0 and platforms(bumped, "99.0.0") == {"linux", "osx", "windows"}, out)
    block = meta.read_text().split('version="99.0.0-1">')[1].split("</component>")[0]
    check("aapt2: sorted linux, osx, windows", block.index("linux") < block.index("osx") < block.index("windows"), block)
    check("aapt2: a second run adds nothing", "added nothing" in run("aapt2_platforms.py", bumped, "--offline-sums", sums)[1])

    code, out = run("verification_additions.py", old, old)
    check("additions: the file against itself", code == 0, out)
    code, out = run("verification_additions.py", old, meta)
    check("additions: a new component with three jars passes", code == 0 and "1 components and 3 artifacts added" in out, out)

    def variant(name, old_text, new_text):
        text = old.read_text()
        assert old_text in text, old_text
        path = work / f"{name}.xml"
        path.write_text(text.replace(old_text, new_text, 1))
        return run("verification_additions.py", old, path)[0]

    first = re.search(r'      <component group="[^"]+" name="[^"]+" version="[^"]+">\n.*?</component>\n', old.read_text(), re.S).group(0)
    pinned = re.search(r'<sha256 value="([0-9a-f]{64})"[^/]*/>', first)
    sha, line = pinned.group(1), pinned.group(0)
    check("additions: a changed hash is refused", variant("changed", line, line.replace(sha, "0" * 64)) == 1)
    check("additions: an also-trust on a pinned jar is refused", variant(
        "alsotrust", line, line[:-2] + f'>\n<also-trust value="{"a" * 64}"/>\n</sha256>') == 1)
    check("additions: a second checksum on a pinned jar is refused", variant(
        "second", line, line + f'\n<sha512 value="{"b" * 128}"/>') == 1)
    check("additions: an origin edit alone passes", variant(
        "origin", line, re.sub(r'origin="[^"]*"', 'origin="Verified by hand"', line)) == 0)
    check("additions: a removed component is refused", variant("removed", first, "") == 1)
    check("additions: a new trust rule is refused", variant(
        "trust", '<trust file=".*-sources[.]jar" regex="true"/>',
        '<trust file=".*-sources[.]jar" regex="true"/>\n<trust file=".*[.]jar" regex="true"/>') == 1)
    check("additions: verify-metadata turned on is refused", variant(
        "verify", "<verify-metadata>false</verify-metadata>", "<verify-metadata>true</verify-metadata>") == 1)
    weak = re.sub(r'version="[^"]+"', 'version="99.9.9"', first, count=1).replace(
        "<sha256 value=", "<sha1 value=").replace(sha, "c" * 40)
    check("additions: a new artifact pinned by sha1 is refused", variant("weak", first, first + weak) == 1)
    check("additions: a DOCTYPE is refused", variant(
        "doctype", '<?xml version="1.0" encoding="UTF-8"?>', '<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE x>') != 0)

    # What Gradle's namespace-blind, flag-driven reader takes as trust and ElementTree alone would miss.
    evil = f'<sha256 value="{"e" * 64}" origin="Generated by Gradle"/>'
    artifact = re.search(r' *<artifact name="[^"]+">\n.*?</artifact>\n', first, re.S).group(0)
    component = first
    check("additions: a second configuration trusting everything is refused", variant(
        "config2", "</components>",
        '</components>\n<configuration><trusted-artifacts><trust group=".*" regex="true"/>'
        '</trusted-artifacts></configuration>') != 0)
    check("additions: a pinned artifact listed twice, another hash first, is refused", variant(
        "dup-artifact", artifact, artifact.replace(line, evil) + artifact) != 0)
    check("additions: an also-trust in another namespace is refused", variant(
        "ns-also", line, line[:-2] + f'><also-trust xmlns="urn:x" value="{"e" * 64}"/></sha256>') != 0)
    check("additions: a components element in another namespace is refused", variant(
        "ns-components", "</components>",
        f'</components><components xmlns="urn:x">{component.replace(sha, "e" * 64)}</components>') != 0)
    check("additions: a checksum nested in a pinned checksum is refused", variant(
        "nested", line, line[:-2] + f">{evil}</sha256>") != 0)
    check("additions: a prefixed element is refused", variant(
        "prefixed", component, component + component.replace("<component ", '<x:component xmlns:x="urn:x" ', 1)
        .replace("</component>", "</x:component>").replace(sha, "e" * 64)) != 0)
    check("additions: an unknown element wrapping an artifact is refused", variant(
        "wrapped", artifact, artifact + f"<wrap>{artifact.replace(line, evil)}</wrap>\n") != 0)

    print(f"{len(failed)} failed")
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
